import { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { 
  PieChart, 
  Pie, 
  Cell, 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer 
} from 'recharts';
import { Award, TrendingUp, AlertTriangle, CheckCircle, Edit, Trash2, Target, Users, Calendar, DollarSign } from 'lucide-react';
import { 
  getAwardPoints, 
  deleteAwardPoint, 
  updateAwardPoint,
  getDepartments,
  getInitiatives
} from '../lib/database';
import { useToast } from '../hooks/use-toast';
import { formatCurrencyDisplay } from '../lib/currency';

const COLORS = {
  primary: 'var(--brand-orange)',
  secondary: 'var(--brand-gray)',
  success: '#16a34a',
  warning: '#eab308',
  danger: '#dc2626',
  info: '#0ea5e9'
};

const STATUS_COLORS = {
  'مكتملة': 'bg-green-100 text-green-800',
  'قيد التنفيذ': 'bg-yellow-100 text-yellow-800',
  'متأخرة': 'bg-red-100 text-red-800',
  'لم تبدأ': 'bg-gray-100 text-gray-800'
};

const POINT_TYPE_COLORS = {
  'نقطة قوة': COLORS.success,
  'نقطة تحسين': COLORS.warning
};

function AwardTab({ statistics, onDataUpdate }) {
  const { toast } = useToast();
  const [awardPoints, setAwardPoints] = useState([]);
  const [departments, setDepartments] = useState([]);
  const [initiatives, setInitiatives] = useState([]);
  const [filteredPoints, setFilteredPoints] = useState([]);
  const [typeFilter, setTypeFilter] = useState('الكل');
  const [criteriaFilter, setCriteriaFilter] = useState('الكل');
  const [editingId, setEditingId] = useState(null);
  const [editData, setEditData] = useState({});

  useEffect(() => {
    loadData();
  }, []);

  useEffect(() => {
    filterPoints();
  }, [awardPoints, typeFilter, criteriaFilter]);

  const loadData = async () => {
    try {
      const [pointsData, departmentsData, initiativesData] = await Promise.all([
        getAwardPoints(),
        getDepartments(),
        getInitiatives()
      ]);
      setAwardPoints(pointsData);
      setDepartments(departmentsData);
      setInitiatives(initiativesData);
    } catch (error) {
      console.error('Error loading data:', error);
      toast({
        title: "خطأ",
        description: "حدث خطأ في تحميل البيانات",
        variant: "destructive",
      });
    }
  };

  const filterPoints = () => {
    let filtered = awardPoints;
    
    if (typeFilter !== 'الكل') {
      filtered = filtered.filter(point => point.type === typeFilter);
    }
    
    if (criteriaFilter !== 'الكل') {
      filtered = filtered.filter(point => point.criteria === criteriaFilter);
    }
    
    setFilteredPoints(filtered);
  };

  // Calculate statistics
  const totalPoints = awardPoints.length;
  const strengthPoints = awardPoints.filter(p => p.type === 'نقطة قوة').length;
  const improvementPoints = awardPoints.filter(p => p.type === 'نقطة تحسين').length;
  const completedPoints = awardPoints.filter(p => p.status === 'مكتملة').length;
  const completionRate = totalPoints > 0 ? Math.round((completedPoints / totalPoints) * 100) : 0;

  // Chart data
  const typeDistribution = [
    { name: 'نقاط القوة', value: strengthPoints, color: COLORS.success },
    { name: 'نقاط التحسين', value: improvementPoints, color: COLORS.warning }
  ];

  const criteriaDistribution = awardPoints.reduce((acc, point) => {
    const existing = acc.find(item => item.name === point.criteria);
    if (existing) {
      existing.value += 1;
    } else {
      acc.push({ name: point.criteria, value: 1, color: COLORS.primary });
    }
    return acc;
  }, []);

  const departmentDistribution = awardPoints.reduce((acc, point) => {
    const existing = acc.find(item => item.name === point.department);
    if (existing) {
      existing.value += 1;
    } else {
      acc.push({ name: point.department, value: 1, color: COLORS.secondary });
    }
    return acc;
  }, []);

  // Progress tracking data
  const progressData = [
    {
      title: 'نسبة الإكمال 0-25%',
      count: initiatives.filter(i => i.completion_percentage >= 0 && i.completion_percentage <= 25).length,
      total: initiatives.length,
      percentage: initiatives.length > 0 ? Math.round((initiatives.filter(i => i.completion_percentage >= 0 && i.completion_percentage <= 25).length / initiatives.length) * 100) : 0,
      color: 'bg-red-500'
    },
    {
      title: 'نسبة الإكمال 26-50%',
      count: initiatives.filter(i => i.completion_percentage >= 26 && i.completion_percentage <= 50).length,
      total: initiatives.length,
      percentage: initiatives.length > 0 ? Math.round((initiatives.filter(i => i.completion_percentage >= 26 && i.completion_percentage <= 50).length / initiatives.length) * 100) : 0,
      color: 'bg-yellow-500'
    },
    {
      title: 'نسبة الإكمال 51-75%',
      count: initiatives.filter(i => i.completion_percentage >= 51 && i.completion_percentage <= 75).length,
      total: initiatives.length,
      percentage: initiatives.length > 0 ? Math.round((initiatives.filter(i => i.completion_percentage >= 51 && i.completion_percentage <= 75).length / initiatives.length) * 100) : 0,
      color: 'bg-blue-500'
    },
    {
      title: 'نسبة الإكمال 76-100%',
      count: initiatives.filter(i => i.completion_percentage >= 76 && i.completion_percentage <= 100).length,
      total: initiatives.length,
      percentage: initiatives.length > 0 ? Math.round((initiatives.filter(i => i.completion_percentage >= 76 && i.completion_percentage <= 100).length / initiatives.length) * 100) : 0,
      color: 'bg-green-500'
    }
  ];

  const budgetEfficiency = initiatives.length > 0 ? 
    Math.round((initiatives.reduce((sum, i) => sum + (i.planned_budget - i.used_budget), 0) / initiatives.reduce((sum, i) => sum + i.planned_budget, 0)) * 100) : 0;

  const scheduleCompliance = initiatives.length > 0 ? 
    Math.round((initiatives.filter(i => i.status === 'مكتملة' || i.status === 'قيد التنفيذ').length / initiatives.length) * 100) : 0;

  const handleDelete = async (id) => {
    if (!confirm('هل أنت متأكد من حذف هذه النقطة؟')) return;
    
    try {
      await deleteAwardPoint(id);
      await loadData();
      onDataUpdate?.();
      toast({
        title: "تم الحذف",
        description: "تم حذف النقطة بنجاح",
      });
    } catch (error) {
      console.error('Error deleting award point:', error);
      toast({
        title: "خطأ",
        description: "حدث خطأ في حذف النقطة",
        variant: "destructive",
      });
    }
  };

  const handleEdit = (point) => {
    setEditingId(point.id);
    setEditData({ ...point });
  };

  const handleSave = async () => {
    try {
      await updateAwardPoint(editingId, editData);
      await loadData();
      onDataUpdate?.();
      setEditingId(null);
      setEditData({});
      toast({
        title: "تم الحفظ",
        description: "تم تحديث النقطة بنجاح",
      });
    } catch (error) {
      console.error('Error updating award point:', error);
      toast({
        title: "خطأ",
        description: "حدث خطأ في تحديث النقطة",
        variant: "destructive",
      });
    }
  };

  const handleCancel = () => {
    setEditingId(null);
    setEditData({});
  };

  return (
    <div className="space-y-6">
      {/* Key Metrics - Moved progress tracking to Overview tab */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <Card>
          <CardContent className="p-4">
            <div className="flex items-center justify-between mb-3">
              <div className="flex items-center gap-2">
                <DollarSign className="h-4 w-4" style={{color: 'var(--brand-orange)'}} />
                <span className="text-xs font-medium text-gray-600">ميزانية</span>
              </div>
            </div>
            <h3 className="text-sm font-semibold text-gray-800 mb-2">كفاءة الميزانية</h3>
            <div className="space-y-2">
              <div className="flex items-center justify-between text-xs text-gray-600">
                <span>التقدم</span>
                <span>{budgetEfficiency} / 100</span>
              </div>
              <div className="w-full bg-gray-200 rounded-full h-2">
                <div 
                  className="h-2 rounded-full bg-blue-500"
                  style={{ width: `${budgetEfficiency}%` }}
                ></div>
              </div>
              <div className="text-xs text-gray-500">
                توفير {budgetEfficiency}% من الميزانية المخططة
              </div>
              <div className="flex items-center justify-between">
                <span className="text-xs text-gray-600">نسبة الإنجاز</span>
                <span className="text-sm font-bold text-gray-800">{budgetEfficiency}%</span>
              </div>
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardContent className="p-4">
            <div className="flex items-center justify-between mb-3">
              <div className="flex items-center gap-2">
                <Calendar className="h-4 w-4" style={{color: 'var(--brand-orange)'}} />
                <span className="text-xs font-medium text-gray-600">جدولة</span>
              </div>
            </div>
            <h3 className="text-sm font-semibold text-gray-800 mb-2">الالتزام بالجدولة</h3>
            <div className="space-y-2">
              <div className="flex items-center justify-between text-xs text-gray-600">
                <span>التقدم</span>
                <span>{scheduleCompliance} / 100</span>
              </div>
              <div className="w-full bg-gray-200 rounded-full h-2">
                <div 
                  className="h-2 rounded-full bg-green-500"
                  style={{ width: `${scheduleCompliance}%` }}
                ></div>
              </div>
              <div className="text-xs text-gray-500">
                {Math.round((scheduleCompliance / 100) * initiatives.length)} من {initiatives.length} مبادرة في الموعد المحدد
              </div>
              <div className="flex items-center justify-between">
                <span className="text-xs text-gray-600">نسبة الإنجاز</span>
                <span className="text-sm font-bold text-gray-800">{scheduleCompliance}%</span>
              </div>
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardContent className="p-4">
            <div className="space-y-3">
              <div className="flex items-center justify-between">
                <span className="text-sm font-medium text-gray-600">إجمالي الإشعارات</span>
                <span className="text-2xl font-bold" style={{color: 'var(--brand-orange)'}}>{totalPoints}</span>
              </div>
              <div className="space-y-2">
                <div className="flex items-center justify-between text-xs">
                  <span className="text-red-600">تحذيرات عالية الأولوية</span>
                  <span className="font-semibold">{improvementPoints}</span>
                </div>
                <div className="flex items-center justify-between text-xs">
                  <span className="text-green-600">إنجازات محققة</span>
                  <span className="font-semibold">{strengthPoints}</span>
                </div>
                <div className="flex items-center justify-between text-xs">
                  <span className="text-blue-600">معدل التقدم</span>
                  <span className="font-semibold">{completionRate}%</span>
                </div>
              </div>
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Award Statistics */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <Card>
          <CardContent className="p-4">
            <div className="flex items-center justify-between mb-2">
              <span className="text-sm font-medium text-gray-600">عدد نقاط القوة</span>
              <CheckCircle className="h-5 w-5 text-green-600" />
            </div>
            <div className="text-2xl font-bold text-green-600">{strengthPoints}</div>
            <div className="text-xs text-gray-500">نقاط إيجابية محددة</div>
          </CardContent>
        </Card>

        <Card>
          <CardContent className="p-4">
            <div className="flex items-center justify-between mb-2">
              <span className="text-sm font-medium text-gray-600">عدد نقاط التحسين</span>
              <AlertTriangle className="h-5 w-5 text-yellow-600" />
            </div>
            <div className="text-2xl font-bold text-yellow-600">{improvementPoints}</div>
            <div className="text-xs text-gray-500">نقاط تحتاج تطوير</div>
          </CardContent>
        </Card>

        <Card>
          <CardContent className="p-4">
            <div className="flex items-center justify-between mb-2">
              <span className="text-sm font-medium text-gray-600">نسبة الإنجاز في الجائزة</span>
              <Award className="h-5 w-5" style={{color: 'var(--brand-orange)'}} />
            </div>
            <div className="text-2xl font-bold" style={{color: 'var(--brand-orange)'}}>{completionRate}%</div>
            <div className="text-xs text-gray-500">من النقاط المكتملة</div>
          </CardContent>
        </Card>

        <Card>
          <CardContent className="p-4">
            <div className="flex items-center justify-between mb-2">
              <span className="text-sm font-medium text-gray-600">عدد المعايير</span>
              <Target className="h-5 w-5 text-blue-600" />
            </div>
            <div className="text-2xl font-bold text-blue-600">{criteriaDistribution.length}</div>
            <div className="text-xs text-gray-500">معيار مختلف</div>
          </CardContent>
        </Card>
      </div>

      {/* Charts Section */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Type Distribution */}
        <Card>
          <CardHeader>
            <CardTitle className="text-lg" style={{color: 'var(--brand-orange)'}}>توزيع النقاط حسب النوع</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="h-64">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={typeDistribution}
                    cx="50%"
                    cy="50%"
                    innerRadius={40}
                    outerRadius={80}
                    paddingAngle={5}
                    dataKey="value"
                  >
                    {typeDistribution.map((entry, index) => (
                      <Cell key={`cell-${index}`} fill={entry.color} />
                    ))}
                  </Pie>
                  <Tooltip />
                </PieChart>
              </ResponsiveContainer>
            </div>
            <div className="flex justify-center gap-4 mt-4">
              {typeDistribution.map((item, index) => (
                <div key={index} className="flex items-center gap-2">
                  <div 
                    className="w-3 h-3 rounded-full" 
                    style={{ backgroundColor: item.color }}
                  ></div>
                  <span className="text-xs text-gray-600">{item.name}: {item.value}</span>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>

        {/* Criteria Distribution */}
        <Card>
          <CardHeader>
            <CardTitle className="text-lg" style={{color: 'var(--brand-orange)'}}>توزيع النقاط حسب المعيار</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="h-64">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={criteriaDistribution}>
                  <CartesianGrid strokeDasharray="3 3" />
                  <XAxis dataKey="name" />
                  <YAxis />
                  <Tooltip />
                  <Bar dataKey="value" fill="var(--brand-orange)" />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </CardContent>
        </Card>

        {/* Department Distribution */}
        <Card>
          <CardHeader>
            <CardTitle className="text-lg" style={{color: 'var(--brand-orange)'}}>توزيع النقاط حسب الإدارة</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="h-64">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={departmentDistribution}>
                  <CartesianGrid strokeDasharray="3 3" />
                  <XAxis dataKey="name" />
                  <YAxis />
                  <Tooltip />
                  <Bar dataKey="value" fill="var(--brand-gray)" />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Filters */}
      <Card>
        <CardHeader>
          <CardTitle className="text-lg" style={{color: 'var(--brand-orange)'}}>الفلاتر</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                تصفية حسب نوع النقطة
              </label>
              <div className="flex gap-2">
                {['الكل', 'نقطة قوة', 'نقطة تحسين'].map((type) => (
                  <Button
                    key={type}
                    variant={typeFilter === type ? "default" : "outline"}
                    size="sm"
                    onClick={() => setTypeFilter(type)}
                    style={typeFilter === type ? {backgroundColor: 'var(--brand-orange)'} : {}}
                  >
                    {type}
                  </Button>
                ))}
              </div>
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                تصفية حسب المعيار
              </label>
              <div className="flex gap-2 flex-wrap">
                <Button
                  variant={criteriaFilter === 'الكل' ? "default" : "outline"}
                  size="sm"
                  onClick={() => setCriteriaFilter('الكل')}
                  style={criteriaFilter === 'الكل' ? {backgroundColor: 'var(--brand-orange)'} : {}}
                >
                  الكل
                </Button>
                {[...new Set(awardPoints.map(p => p.criteria))].map((criteria) => (
                  <Button
                    key={criteria}
                    variant={criteriaFilter === criteria ? "default" : "outline"}
                    size="sm"
                    onClick={() => setCriteriaFilter(criteria)}
                    style={criteriaFilter === criteria ? {backgroundColor: 'var(--brand-orange)'} : {}}
                  >
                    {criteria}
                  </Button>
                ))}
              </div>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Award Points Table */}
      <Card>
        <CardHeader>
          <CardTitle className="text-lg" style={{color: 'var(--brand-orange)'}}>تفاصيل نقاط الجائزة</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="overflow-x-auto">
            <table className="w-full border-collapse">
              <thead>
                <tr className="border-b border-gray-200">
                  <th className="text-right p-3 font-medium text-gray-700">الرقم</th>
                  <th className="text-right p-3 font-medium text-gray-700">نوع النقطة</th>
                  <th className="text-right p-3 font-medium text-gray-700">المعيار</th>
                  <th className="text-right p-3 font-medium text-gray-700">تصنيف المعيار</th>
                  <th className="text-right p-3 font-medium text-gray-700">الإدارة</th>
                  <th className="text-right p-3 font-medium text-gray-700">الوصف</th>
                  <th className="text-right p-3 font-medium text-gray-700">الحالة</th>
                  <th className="text-right p-3 font-medium text-gray-700">المسؤول</th>
                  <th className="text-center p-3 font-medium text-gray-700">الإجراءات</th>
                </tr>
              </thead>
              <tbody>
                {filteredPoints.map((point, index) => (
                  <tr key={point.id} className="border-b border-gray-100 hover:bg-gray-50">
                    <td className="p-3 text-sm">{index + 1}</td>
                    <td className="p-3">
                      <Badge 
                        className="text-xs"
                        style={{ 
                          backgroundColor: point.type === 'نقطة قوة' ? COLORS.success : COLORS.warning,
                          color: 'white'
                        }}
                      >
                        {point.type}
                      </Badge>
                    </td>
                    <td className="p-3 text-sm">{point.criteria}</td>
                    <td className="p-3 text-sm">{point.criteria_category}</td>
                    <td className="p-3 text-sm">{point.department}</td>
                    <td className="p-3 text-sm max-w-xs truncate" title={point.description}>
                      {point.description}
                    </td>
                    <td className="p-3">
                      <Badge className={`text-xs ${STATUS_COLORS[point.status] || 'bg-gray-100 text-gray-800'}`}>
                        {point.status}
                      </Badge>
                    </td>
                    <td className="p-3 text-sm">{point.responsible_person}</td>
                    <td className="p-3">
                      <div className="flex items-center justify-center gap-2">
                        <Button
                          size="sm"
                          variant="outline"
                          onClick={() => handleEdit(point)}
                          className="h-8 w-8 p-0"
                        >
                          <Edit className="h-3 w-3" />
                        </Button>
                        <Button
                          size="sm"
                          variant="outline"
                          onClick={() => handleDelete(point.id)}
                          className="h-8 w-8 p-0 text-red-600 hover:text-red-700"
                        >
                          <Trash2 className="h-3 w-3" />
                        </Button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
            {filteredPoints.length === 0 && (
              <div className="text-center py-8 text-gray-500">
                لا توجد نقاط تطابق معايير البحث
              </div>
            )}
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

export default AwardTab;
